// Enclosure for Wisp Air Quality Monitor
// Outer: 115 x 85 x 40 mm, Wall: 2 mm

$fn = 40;
wall = 2.0;
w = 115; d = 85; h = 40;
r = 4;

module rounded_box(x, y, z, rad) {
    hull() {
        translate([-x/2 + rad, -y/2 + rad, 0]) cylinder(r=rad, h=z);
        translate([ x/2 - rad, -y/2 + rad, 0]) cylinder(r=rad, h=z);
        translate([-x/2 + rad,  y/2 - rad, 0]) cylinder(r=rad, h=z);
        translate([ x/2 - rad,  y/2 - rad, 0]) cylinder(r=rad, h=z);
    }
}

// Base with air ventilation grilles
module wisp_base() {
    difference() {
        rounded_box(w, d, h - 8, r);
        translate([0, 0, wall])
            rounded_box(w - 2*wall, d - 2*wall, h, r - 1);

        // MicroUSB power port for ESP32
        translate([-w/2 - 1, 14, 4])
            cube([wall + 2, 10, 6]);

        // Ventilation slots on right side for MQ-135 airflow
        for (i = [-12:6:12]) {
            translate([w/2 - 1, 16 + i, 10])
                cube([wall + 2, 3, 15]);
        }
    }
}

// Snap-fit Lid with OLED cutout and grill
module wisp_lid() {
    translate([0, 0, h + 10]) {
        difference() {
            union() {
                rounded_box(w, d, 8, r);
                translate([0, 0, -3])
                    rounded_box(w - 2*wall - 0.4, d - 2*wall - 0.4, 3, r - 1);
            }
            // OLED cutout
            translate([-24, -20, -1])
                cube([25, 15, 12], center=true);
            // Buzzer acoustic pinhole
            translate([4, 0, -1])
                cylinder(r=1.5, h=12);
        }
    }
}

wisp_base();
wisp_lid();

