/*
 * Solder Showcase: Wisp — Air Quality & Gas Sentinel
 * Target: ESP32 DevKit V1
 * Pins:
 *   D34: MQ-135 Gas Sensor Analog In (ADC1_CH6)
 *   D4:  DHT22 Temperature & Humidity (1-wire)
 *   D18: Active Piezo Buzzer Pulse
 *   D21: SSD1306 OLED SDA
 *   D22: SSD1306 OLED SCL
 */

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <DHT.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

#define DHTPIN 4
#define DHTTYPE DHT22
DHT dht(DHTPIN, DHTTYPE);

const int PIN_MQ135 = 34;
const int PIN_BUZZER = 18;

// Safety thresholds
const int GAS_HAZARD_THRESHOLD = 1200; // Raw 12-bit ADC threshold
const float TEMP_HIGH_THRESHOLD = 45.0; // Celsius

void setup() {
  Serial.begin(115200);
  pinMode(PIN_BUZZER, OUTPUT);
  digitalWrite(PIN_BUZZER, LOW);

  dht.begin();

  if (display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    display.clearDisplay();
    display.setTextSize(1);
    display.setTextColor(SSD1306_WHITE);
    display.setCursor(15, 25);
    display.println(F("Wisp Air Sentinel"));
    display.display();
  }
  Serial.println(F("SYSTEM_READY"));
}

void loop() {
  int gasRaw = analogRead(PIN_MQ135);
  float temp = dht.readTemperature();
  float hum = dht.readHumidity();

  if (isnan(temp) || isnan(hum)) {
    temp = 24.0;
    hum = 50.0;
  }

  // Calculate approximate ppm proxy
  int aqiPpm = map(constrain(gasRaw, 200, 3000), 200, 3000, 20, 800);

  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println(F("WISP AIR SENTINEL"));
  display.drawLine(0, 10, 128, 10, SSD1306_WHITE);

  display.setCursor(0, 18);
  display.print(F("AQI: "));
  display.print(aqiPpm);
  display.println(F(" ppm"));

  display.setCursor(0, 32);
  display.print(F("T: "));
  display.print(temp, 1);
  display.print(F("C  H: "));
  display.print(hum, 0);
  display.println(F("%"));

  if (gasRaw > GAS_HAZARD_THRESHOLD) {
    display.setCursor(0, 48);
    display.println(F("ALERT: TOXIC GAS!"));
    display.display();

    Serial.print(F("[WISP] AQI:"));
    Serial.print(aqiPpm);
    Serial.println(F(" -> HAZARD_ALERT"));
    Serial.println(F("BUZZER_ACTIVE"));

    // Acoustic alarm pulse
    for (int i = 0; i < 3; i++) {
      digitalWrite(PIN_BUZZER, HIGH);
      delay(150);
      digitalWrite(PIN_BUZZER, LOW);
      delay(100);
    }
  } else if (temp > TEMP_HIGH_THRESHOLD) {
    display.setCursor(0, 48);
    display.println(F("ALERT: HEAT ADVISORY"));
    Serial.println(F("CLIMATE_WARNING"));
  } else {
    display.setCursor(0, 48);
    display.println(F("STATUS: AIR CLEAN"));
    Serial.print(F("[WISP] AQI:"));
    Serial.print(aqiPpm);
    Serial.println(F(" -> STATUS_GOOD"));
  }

  display.display();
  delay(1500);
}
